import {readFile,writeFile,readdir} from 'node:fs/promises';import {createHash} from 'node:crypto';
const phase=process.argv[2],environment=process.argv[3];
const refs={PROD:'YOUR_PROJECT_REF',DEV:'YOUR_PROJECT_REF'},initial={PROD:451,DEV:429};
if(!refs[environment]||!['prepare','dry-run','apply','observe','recover-backend'].includes(phase))throw Error('Explicit FVI target/phase required');
const privateRoot='./LOCAL_USER/AppData/Local/FVI-QA-Private-20260925';
const lane=privateRoot+'/governance-approval-hosted-20261002',version='20261004033000';
const base=privateRoot+'/FVI-GOVERNANCE-PT409-'+environment+'-20261004';
const sha=s=>createHash('sha256').update(s).digest('hex'),quote=s=>`'${s.replaceAll("'","''")}'`;
const vault=await readFile('./.private/CREDENTIALS.md','utf8');const a=vault.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_BEGIN -->'),b=vault.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_END -->');if(a<0||b<=a)throw Error('FVI operational vault section absent');
const token=vault.slice(a,b).split(/\r?\n/).find(s=>/^\|\s*`SUPABASE_ACCESS_TOKEN`\s*\|/.test(s))?.split('|')[2]?.trim().replace(/^`|`$/g,'');if(!/^sbp_/.test(token??''))throw Error('FVI management access unavailable');
async function query(sql,readOnly){const r=await fetch(`https://api.supabase.com/v1/projects/${refs[environment]}/database/query`,{method:'POST',headers:{authorization:`Bearer ${token}`,'content-type':'application/json'},body:JSON.stringify({query:sql,read_only:readOnly}),signal:AbortSignal.timeout(120000)});const raw=await r.text();if(!r.ok){const p=base+'-'+phase+'-ERROR-'+Date.now()+'.json';await writeFile(p,JSON.stringify({at:new Date().toISOString(),http:r.status,response:raw},null,2),{flag:'wx'});throw Error('HTTP'+r.status+'; diagnostic retained '+p);}return JSON.parse(raw);}
const identitySql="SELECT current_setting('server_version_num')::int AS engine,(SELECT count(*) FROM supabase_migrations.schema_migrations)::int AS ledger,(SELECT max(version::text) FROM supabase_migrations.schema_migrations) AS latest";
if(phase==='recover-backend'){
 if(environment!=='PROD')throw Error('Only precisely attributed PROD QA backend is in scope');
 const prepared=JSON.parse(await readFile(base+'-PREPARED.json','utf8')),applied=JSON.parse(await readFile(base+'-APPLY-RECEIPT.json','utf8'));
 if(applied.packetSha256!==prepared.applySha256)throw Error('Verified exact hotfix apply required first');
 const f=prepared.functions.find(x=>x.name==='public.withdraw_governance_membership_request');
 const proof=await query(`SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') AS hash FROM pg_proc WHERE oid=${quote(f.signature)}::regprocedure`,true);if(proof[0]?.hash!==f.afterBody)throw Error('Nonretryable current function not verified');
 const predicate="pid=1165594 AND backend_start='2026-10-03 21:12:09.045582+00'::timestamptz AND usename='authenticator' AND application_name='PostgREST 14.5' AND state='active' AND query LIKE '%withdraw_governance_membership_request%' AND encode(sha256(convert_to(query,'UTF8')),'hex')='7fc4e4021fb49ae10d681ec7716548340a036343314d3b3646f265088d21986d'";
 const before=await query(`SELECT pid,backend_start,usename,application_name,state FROM pg_stat_activity WHERE ${predicate}`,true);
 const result=before.length===1?await query(`SELECT pid,pg_terminate_backend(pid,5000) AS terminated FROM pg_stat_activity WHERE ${predicate}`,false):[];
 const after=await query("SELECT pid,backend_start,usename,application_name,state FROM pg_stat_activity WHERE pid=1165594",true);
 const receipt={at:new Date().toISOString(),environment,scope:'exact provider-log-attributed runaway QA withdrawal backend only',pid:1165594,before,result,after,unrelatedBackendsAffected:0,authIdentitiesCredentialsRolesSessionsModified:false,matchingOldBackendAbsent:!after.some(x=>x.backend_start==='2026-10-03 21:12:09.045582+00')};
 const p=base+'-BACKEND-RECOVERY-'+Date.now()+'.json';await writeFile(p,JSON.stringify(receipt,null,2),{flag:'wx'});console.log(JSON.stringify({file:p,matched:before.length,terminated:result[0]?.terminated??false,matchingOldBackendAbsent:receipt.matchingOldBackendAbsent}));
}else if(phase==='observe'){
 const rows=await query("SELECT pid,backend_start,usename,application_name,state,wait_event_type,wait_event,pg_blocking_pids(pid) AS blockers,query_start,(query LIKE '%withdraw_governance_membership_request%') AS is_withdrawal,encode(sha256(convert_to(query,'UTF8')),'hex') AS query_sha256 FROM pg_stat_activity WHERE pid=1165594",true);
 const p=base+'-BACKEND-READONLY-'+Date.now()+'.json';await writeFile(p,JSON.stringify({at:new Date().toISOString(),environment,read_only:true,rows},null,2),{flag:'wx'});console.log(JSON.stringify({file:p,rows}));
}else if(phase==='prepare'){
 const proposal=JSON.parse(await readFile(lane+'/GOVERNANCE-BUSINESS-CONFLICT-PROPOSAL-20261004-v2.json','utf8')).environments[environment];
 const source=await readFile(proposal.proposal_file,'utf8');if(sha(source)!==proposal.proposal_sha256)throw Error('Frozen six-function proposal changed');
 const signatures=proposal.changed.map(x=>x.function),metadata=await query(`SELECT p.oid::text AS oid, n.nspname||'.'||p.proname AS name,pg_get_function_identity_arguments(p.oid) AS identity,p.prosrc AS body,p.proowner::text AS owner,p.prosecdef AS definer,p.proconfig AS config,p.proacl::text AS acl,pg_get_function_result(p.oid) AS result,p.proargnames AS argument_names,p.proargtypes::text AS argument_types FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.oid=ANY(ARRAY[${signatures.map(s=>quote(s)+'::regprocedure').join(',')}])`,true);
 const matches=[...source.matchAll(/CREATE OR REPLACE FUNCTION\s+([\w]+\.[\w]+)[\s\S]*?AS (\$[\w]+\$)([\s\S]*?)\2;/g)];if(matches.length!==6||metadata.length!==6)throw Error('Exact six-function source boundary changed');
 const post=[];
 for(const f of metadata){const spec=proposal.changed.find(s=>s.function.split('(')[0]===f.name),m=matches.find(x=>x[1]===f.name);if(!spec||!m||sha(f.body)!==spec.before_body_sha256)throw Error('Native source preimage drift: '+f.name);
  const raises=[...f.body.matchAll(/ERRCODE\s*=\s*'40001'/g)];if(raises.length!==spec.business_raises)throw Error('Business conflict site count changed');
  let expected=f.body.replace(/(ERRCODE\s*=\s*)'40001'/g,"$1'PT409'");if(spec.snapshot_catch_changed){const old="EXCEPTION WHEN SQLSTATE '40001'";if(!expected.includes(old))throw Error('Exact snapshot catch absent');expected=expected.replace(old,"EXCEPTION WHEN SQLSTATE 'PT409'");}
  if(expected!==m[3])throw Error('Proposal changes more than exact business error codes: '+f.name);post.push({name:f.name,signature:spec.function,beforeBody:sha(f.body),afterBody:sha(expected)});
 }
 const id=await query(identitySql,true);if(id[0]?.engine!==170006||id[0]?.ledger!==initial[environment]||id[0]?.latest!=='20261003180000')throw Error('Current target identity changed');
 const body=source.replace(/^BEGIN;\s*$/m,'').replace(/^COMMIT;\s*$/m,'').trim();
 const names=[...new Set([...source.matchAll(/public\.([a-z_][a-z0-9_]*)/g)].map(x=>x[1]))];
 let sql=`BEGIN; SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='90s'; SET LOCAL search_path=pg_catalog,public,private;\nDO $ledger$ BEGIN IF (SELECT count(*) FROM supabase_migrations.schema_migrations)<>${initial[environment]} OR (SELECT max(version::text) FROM supabase_migrations.schema_migrations)<>'20261003180000' OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version=${quote(version)}) THEN RAISE EXCEPTION 'PT409 exact ledger/version preimage changed'; END IF; END $ledger$;\nLOCK TABLE supabase_migrations.schema_migrations IN SHARE ROW EXCLUSIVE MODE;\nCREATE TEMP TABLE _pt409_oldledger AS SELECT encode(sha256(convert_to(jsonb_agg(to_jsonb(m) ORDER BY version)::text,'UTF8')),'hex') AS sha FROM supabase_migrations.schema_migrations m;\n`;
 sql+=`CREATE TEMP TABLE _pt409_oldfunctions AS SELECT p.oid,p.proowner,p.prosecdef,p.proconfig,p.proacl,p.proargnames,p.proargtypes,pg_get_function_result(p.oid) AS result FROM pg_proc p WHERE p.oid=ANY(ARRAY[${signatures.map(s=>quote(s)+'::regprocedure').join(',')}]);\nCREATE TEMP TABLE _pt409_oldrows(schema_name text,table_name text,sha text);\nDO $snapshot$ DECLARE r record;v text;BEGIN FOR r IN SELECT n.nspname AS schema_name,c.relname AS table_name FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') AND c.relname=ANY(ARRAY[${names.map(quote).join(',')}]) ORDER BY c.relname LOOP EXECUTE format('LOCK TABLE %I.%I IN SHARE MODE',r.schema_name,r.table_name);EXECUTE format('SELECT encode(sha256(convert_to(coalesce(jsonb_agg(x.rowdata ORDER BY x.rowdata::text),''[]''::jsonb)::text,''UTF8'')),''hex'') FROM (SELECT to_jsonb(t) AS rowdata FROM %I.%I t)x',r.schema_name,r.table_name) INTO v;INSERT INTO _pt409_oldrows VALUES(r.schema_name,r.table_name,v);END LOOP;END $snapshot$;\n`;
 sql+=body+'\nDO $preserve$ DECLARE r record;v text;BEGIN FOR r IN SELECT * FROM _pt409_oldrows LOOP EXECUTE format(\'SELECT encode(sha256(convert_to(coalesce(jsonb_agg(x.rowdata ORDER BY x.rowdata::text),\'\'[]\'\'::jsonb)::text,\'\'UTF8\'\')),\'\'hex\'\') FROM (SELECT to_jsonb(t) AS rowdata FROM %I.%I t)x\',r.schema_name,r.table_name) INTO v;IF v IS DISTINCT FROM r.sha THEN RAISE EXCEPTION \'PT409 changed old business rows\';END IF;END LOOP;IF EXISTS(SELECT 1 FROM _pt409_oldfunctions o LEFT JOIN pg_proc p ON p.oid=o.oid WHERE p.oid IS NULL OR ROW(p.proowner,p.prosecdef,p.proconfig,p.proacl,p.proargnames,p.proargtypes,pg_get_function_result(p.oid)) IS DISTINCT FROM ROW(o.proowner,o.prosecdef,o.proconfig,o.proacl,o.proargnames,o.proargtypes,o.result)) THEN RAISE EXCEPTION \'PT409 authority or ABI changed\';END IF;END $preserve$;\n';
 for(const f of post)sql+=`DO $post$ BEGIN IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid=${quote(f.signature)}::regprocedure) IS DISTINCT FROM ${quote(f.afterBody)} THEN RAISE EXCEPTION 'PT409 exact implementation postimage mismatch';END IF;END $post$;\n`;
 sql+=`INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES(${quote(version)},'governance_business_conflicts_pt409',ARRAY[${quote(source)}]::text[]);\nDO $registered$ BEGIN IF (SELECT count(*) FROM supabase_migrations.schema_migrations)<>${initial[environment]+1} OR (SELECT max(version::text) FROM supabase_migrations.schema_migrations)<>${quote(version)} OR (SELECT encode(sha256(convert_to(jsonb_agg(to_jsonb(m) ORDER BY version)::text,'UTF8')),'hex') FROM supabase_migrations.schema_migrations m WHERE version<>${quote(version)}) IS DISTINCT FROM (SELECT sha FROM _pt409_oldledger) THEN RAISE EXCEPTION 'PT409 old ledger or exact registration mismatch';END IF;END $registered$;NOTIFY pgrst,'reload schema';\n`;
 const prepared={at:new Date().toISOString(),environment,ref:refs[environment],version,initialLedger:initial[environment],expectedLedger:initial[environment]+1,sourceSha256:sha(source),dryRunSha256:sha(sql+'ROLLBACK;\n'),applySha256:sha(sql+'COMMIT;\n'),functions:post,businessRaiseChanges:10,snapshotCatchChanges:1,noPermissionsOrBusinessLogicChanges:true};
 await writeFile(base+'-SOURCE.sql',source,{flag:'wx'});await writeFile(base+'-DRY-RUN.sql',sql+'ROLLBACK;\n',{flag:'wx'});await writeFile(base+'-APPLY.sql',sql+'COMMIT;\n',{flag:'wx'});await writeFile(base+'-PREPARED.json',JSON.stringify(prepared,null,2),{flag:'wx'});console.log(JSON.stringify({environment,prepared:base+'-PREPARED.json',functions:6,businessRaiseChanges:10,snapshotCatchChanges:1,sourceSha256:prepared.sourceSha256}));
}else{
 const prepared=JSON.parse(await readFile(base+'-PREPARED.json','utf8')),sql=await readFile(base+(phase==='dry-run'?'-DRY-RUN.sql':'-APPLY.sql'),'utf8');if(sha(sql)!==(phase==='dry-run'?prepared.dryRunSha256:prepared.applySha256))throw Error('Immutable packet drift');
 if(phase==='apply'){const dry=JSON.parse(await readFile(base+'-DRY-RUN-RECEIPT.json','utf8'));if(!dry.rollbackVerified||dry.packetSha256!==prepared.dryRunSha256)throw Error('Actual exact rollback proof absent');try{await readFile(base+'-APPLY-RECEIPT.json');throw Error('Already committed; readback only');}catch(e){if(e.code!=='ENOENT')throw e;}}
 const before=await query(identitySql,true);if(before[0]?.ledger!==prepared.initialLedger||before[0]?.latest!=='20261003180000')throw Error('Mutable target identity drift');await query(sql,false);const after=await query(identitySql,true);if(phase==='dry-run'&&JSON.stringify(before)!==JSON.stringify(after))throw Error('Rollback identity changed');if(phase==='apply'&&(after[0]?.ledger!==prepared.expectedLedger||after[0]?.latest!==version))throw Error('Committed identity mismatch');
 const receipt={at:new Date().toISOString(),environment,ref:refs[environment],phase,packetSha256:sha(sql),before,after,rollbackVerified:phase==='dry-run',actualWorkflowAcceptance:false};await writeFile(base+(phase==='dry-run'?'-DRY-RUN-RECEIPT.json':'-APPLY-RECEIPT.json'),JSON.stringify(receipt,null,2),{flag:'wx'});console.log(JSON.stringify({environment,phase,verified:true,ledger:after[0].ledger,latest:after[0].latest,appUploadRequired:false}));
}
